import{_ as e,a,b as r,c as o,d as i,e as s}from"./chunks/history.CPoQGR9M.js";import{_ as n,o as d,c as l,a2 as c}from"./chunks/framework.CDA9RsCr.js";const w=JSON.parse('{"title":"Product","description":"","frontmatter":{},"headers":[],"relativePath":"en/intro/product.md","filePath":"en/intro/product.md","lastUpdated":1794581028000}'),h={name:"en/intro/product.md"};function p(m,t,u,k,g,b){return d(),l("div",null,[...t[0]||(t[0]=[c('<h1 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h1><p>BiliLuckyDraw is a desktop app for running lucky draws in Bilibili live streams. Once connected to a room it listens to danmaku in real time: a viewer whose message contains the configured keyword is entered into the draw, and winners are picked at random from all participants. The whole process is automatic — no manual list-keeping, fair and transparent.</p><p>It also folds in the things that otherwise need several windows: the stream player, the room list, the live danmaku feed and the winner list all share one screen, so you don&#39;t juggle a browser and a spreadsheet before going live.</p><p>It&#39;s built for streamers running interactive giveaways — a daily thank-you, a fan-festival event or a holiday special — and starts collecting in seconds.</p><ul><li><strong>Repository</strong>: <a href="https://github.com/aDarkMaker/BiliLuckyDraw" target="_blank" rel="noreferrer">aDarkMaker/BiliLuckyDraw</a></li><li><strong>Releases</strong>: <a href="https://github.com/aDarkMaker/BiliLuckyDraw/releases" target="_blank" rel="noreferrer">github.com/aDarkMaker/BiliLuckyDraw/releases</a></li><li><strong>License</strong>: MIT © 2025 aDarkMaker</li></ul><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li>Monitors danmaku in one or more live rooms in real time</li><li>Enters viewers who send the keyword, deduplicated by UID (multiple messages in the same room count once); an empty keyword collects every danmaku</li><li>One-click draw — randomly picks the configured number of winners and records the result in that profile&#39;s history</li><li>Two login methods: paste a Cookie, or scan a QR code with the mobile app</li><li>Multiple draw configs — keyword, winner count, rooms and background switch together</li><li>Light / dark modes plus spring-festival and beach backdrops; the accent color is sampled from the active image</li><li>Stream player and danmaku feed in the same view; the feed sticks to the bottom, pauses on scroll-up and resumes after a few idle seconds</li></ul><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lottery</th><th>Cookie login</th><th>QR-code login</th></tr></thead><tbody><tr><td><img src="'+e+'" alt="Lottery"></td><td><img src="'+a+'" alt="Login"></td><td><img src="'+r+'" alt="QR code"></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Settings</th><th>Winners</th><th>Draw history</th></tr></thead><tbody><tr><td><img src="'+o+'" alt="Settings"></td><td><img src="'+i+'" alt="Winners"></td><td><img src="'+s+'" alt="Draw history"></td></tr></tbody></table><h2 id="tech-stack" tabindex="-1">Tech stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Tech</th></tr></thead><tbody><tr><td>Backend</td><td>Wails v3 (v3.0.0-alpha.95) · Go 1.25</td></tr><tr><td>Frontend</td><td>React 19 · TypeScript 5 · Vite 6 · Tailwind 3 · HeroUI</td></tr><tr><td>Live protocols</td><td>Danmaku WebSocket binary frames · HLS (hls.js)</td></tr><tr><td>Storage</td><td>Local JSON under <code>~/.luckydraw/</code></td></tr></tbody></table><h2 id="data-stays-local" tabindex="-1">Data stays local <a class="header-anchor" href="#data-stays-local" aria-label="Permalink to &quot;Data stays local&quot;">​</a></h2><p>Credentials, configs and history live in <code>~/.luckydraw/</code> with 0600 permissions. Nothing is uploaded, and the app intentionally provides no cloud sync or automatic prize distribution.</p>',14)])])}const _=n(h,[["render",p]]);export{w as __pageData,_ as default};
